<?php
require __DIR__ . '/auth.php'; require_login(); require __DIR__ . '/conexion.php';
$msg='';
if($_SERVER['REQUEST_METHOD']==='POST'){$pct=filter_var($_POST['impuesto_pct']??null,FILTER_VALIDATE_FLOAT);if($pct!==false&&$pct>=0&&$pct<=100){$s=$mysqli->prepare("INSERT INTO configuracion(clave,valor) VALUES('impuesto_pct',?) ON DUPLICATE KEY UPDATE valor=VALUES(valor)");$val=(string)$pct;$s->bind_param('s',$val);$s->execute();$s->close();$msg='Configuración guardada.';}}
$r=$mysqli->query("SELECT valor FROM configuracion WHERE clave='impuesto_pct'");$tax=$r?$r->fetch_column():'0';
